(9,0,'Auto Parts Fittings','auto-parts-fittings','https://www.hbfittings.net/uploads/33800/small/high-pressure-stainless-steel-pipe-nipple645f7.png','Oxygen sensor fittings, adapters, bungs and specialty automotive components.',0,90,1,NOW(3),NOW(3)),
(10,0,'Reusable Hose Fittings','reusable-hose-fittings','https://www.hbfittings.net/uploads/202633800/small/male-pipe-reusable-hydraulic-hose-fittingc946c90e-98c8-4db7-9ad6-c3bfe40d195f.webp','Field-installable reusable hose fittings for maintenance and repair.',0,100,1,NOW(3),NOW(3)),
(101,1,'Brass Pipe Fittings','brass-pipe-fittings','https://www.hbfittings.net/Content/uploads/2021806904/2021061809482191882e6e776d427097002d6e5c760602.jpg','NPT and BSP nipples, elbows, tees, adapters and couplings.',1,5,1,NOW(3),NOW(3)),
(102,1,'Brass Hose Barb Fittings','brass-hose-barb-fittings','https://www.hbfittings.net/Content/uploads/2021806904/202106180949279a1309ce467e47a5ab7bc552fff7b95f.jpg','Secure hose connections for water, air, fuel and industrial media.',0,20,1,NOW(3),NOW(3)),
(103,1,'Brass Compression Fitting','brass-compression-fitting','https://www.hbfittings.net/Content/uploads/2021806904/202106180949279a1309ce467e47a5ab7bc552fff7b95f.jpg','Reliable compression connections for copper and plastic tubing.',0,30,1,NOW(3),NOW(3)),
(104,1,'Garden Hose Fitting','garden-hose-fitting','https://www.hbfittings.net/uploads/33800/news/n202607291544016baf6.jpg','Standard and custom garden hose adapters and couplings.',0,40,1,NOW(3),NOW(3)),
(201,2,'Brass Ball Valve','brass-ball-valve','https://www.hbfittings.net/uploads/33800/small/600-psi-wog-brass-gas-ball-valve-for-gas39c47.png','Compact and full-port brass ball valves for gas and liquid systems.',0,10,1,NOW(3),NOW(3)),
(301,3,'Pressure Syphon Tube','pressure-syphon-tube','https://www.hbfittings.net/Content/uploads/2021806904/20210618094714fc7ea8c7bc62444280951f16881dd15d.jpg','Coil and pigtail syphon tubes for pressure instrument protection.',0,10,1,NOW(3),NOW(3)),
(601,6,'Compression Tube Fittings','compression-tube-fittings','https://www.hbfittings.net/uploads/33800/small/stainless-steel-threaded-eccentric-couplingc403d.png','Double ferrule tube fittings for high-pressure instrumentation.',0,10,1,NOW(3),NOW(3)),
(701,7,'BSP Standards','bsp-hydraulic-fittings','https://www.hbfittings.net/uploads/33800/small/hydraulic-hose-reusable-fitting1e824.png','BSPP and BSPT hydraulic adapters and hose connections.',0,10,1,NOW(3),NOW(3)),
(702,7,'JIC Standards','jic-hydraulic-fittings','https://www.hbfittings.net/uploads/202633800/small/jic-37-swivel-reusable-hydraulic-hose-fitting1eabf2ce-ba27-4461-a832-ae51e521651e.webp','JIC 37-degree flare hydraulic fittings and adapters.',0,20,1,NOW(3),NOW(3));
INSERT INTO `products` (`id`,`category_id`,`name`,`slug`,`sku`,`summary`,`description`,`main_image`,`video_url`,`material`,`size`,`thread_standard`,`pressure_rating`,`temperature_range`,`moq`,`standard`,`application`,`hot_tags`,`featured`,`latest`,`sort`,`status`,`created_at`,`updated_at`) VALUES
(1,201,'EN331 Approved Nickel Plated Brass Gas Ball Valve','en331-approved-nickel-plated-brass-gas-ball-valve','DP-BV-331','Nickel-plated brass gas ball valve with nozzle and female connection, available for OEM sizing.','<h2>Production Introduction</h2><p>This compact gas ball valve combines a forged brass body, smooth quarter-turn operation and leak-resistant sealing for gas piping systems.</p><h3>Products Feature</h3><ul><li>100% pressure tested before shipment</li><li>Custom thread, handle and logo options</li><li>EN331 configuration available</li></ul><h3>Why Choose Us</h3><p>Depo provides CNC machining, traceable inspection and engineering support from sample to volume production.</p>','https://www.hbfittings.net/uploads/33800/small/en331-approved-nickel-plated-brass-gas-ball52bba.png','','Forged brass, nickel plated','1/4-1/2 in','BSPP / BSPT / NPT','600 PSI WOG','-20 C to 120 C','500 pcs','EN331','Natural gas and LPG piping','brass gas ball valve,EN331 valve,nickel plated valve',1,1,10,1,NOW(3),NOW(3)),
(2,201,'Female x Flare Angle Brass Gas Ball Valve With T Handle','female-flare-angle-brass-gas-ball-valve','DP-BV-A38','Angle-pattern brass gas valve with female inlet, flare outlet and compact T handle.','<h2>Production Introduction</h2><p>Designed for tight installations where a 90-degree change of direction is required. Threads and flare sizes can be customized.</p><h3>Quality Control</h3><p>Every valve receives dimensional, surface and leak testing before packing.</p>','https://www.hbfittings.net/uploads/33800/small/1-2-fip-x-3-8-flare-angle-brass-gas-ballff2b5.png','','Brass','1/4-1 in','Female x SAE flare','600 PSI','-20 C to 120 C','500 pcs','ANSI / OEM','Gas appliance connection','angle gas valve,flare ball valve,T handle valve',1,1,20,1,NOW(3),NOW(3)),
(3,201,'600 PSI WOG Brass Female Gas Ball Valve','600-psi-wog-brass-female-gas-ball-valve','DP-BV-600F','Two-piece female brass ball valve for gas piping systems and industrial service.','<h2>Product Overview</h2><p>A full-flow two-piece construction provides low pressure drop and dependable shutoff. Available with BSPP, BSPT or NPT threads.</p><h3>Customization</h3><p>Body marking, handle color, package and size are available to order.</p>','https://www.hbfittings.net/uploads/33800/small/600-psi-wog-brass-gas-ball-valve-for-gas39c47.png','','Forged brass','1/4-1 in','Female x Female BSP / NPT','600 PSI WOG','-20 C to 120 C','500 pcs','OEM','Gas and water pipeline','600 PSI ball valve,brass valve,female valve',1,1,30,1,NOW(3),NOW(3)),
(4,201,'Brass Flare x Flare Gas Ball Valve','brass-flare-flare-gas-ball-valve','DP-BV-FF','Compact inline flare ball valve manufactured for OEM and ODM gas equipment programs.','<h2>Product Details</h2><p>Precision flare seats support quick assembly and dependable sealing without thread sealant.</p><h3>Applications</h3><p>Suitable for gas appliances, HVAC equipment and instrument utility lines.</p>','https://www.hbfittings.net/uploads/33800/small/brass-flare-x-flare-gas-ball-valve-oem-odm44b23.png','','Brass','1/4-1 in','SAE flare x flare','600 PSI','-20 C to 120 C','500 pcs','SAE / OEM','Gas, HVAC and instrumentation','flare valve,OEM brass valve,gas fitting',1,1,40,1,NOW(3),NOW(3)),
(5,201,'Male Thread Brass Gas Valve With Butterfly Handle','male-thread-brass-gas-valve-butterfly-handle','DP-BV-MF','Compact male-to-flare brass gas valve with a low-profile butterfly handle.','<h2>Production Introduction</h2><p>The compact handle and forged body make this valve ideal for confined gas appliance connections.</p><h3>Options</h3><p>Custom plating, laser logo, thread and packaging are supported.</p>','https://www.hbfittings.net/uploads/33800/small/brass-gas-flare-ball-valve-male-thread-brassd752f.png','','Forged brass','1/4-1 in','Male thread x flare','600 PSI','-20 C to 120 C','500 pcs','OEM','Gas appliance and utility connection','butterfly handle valve,male gas valve,brass valve',1,1,50,1,NOW(3),NOW(3)),
(6,701,'Hydraulic Hose Reusable Fitting','hydraulic-hose-reusable-fitting','DP-HY-RF','Field-installable reusable hydraulic hose fitting for maintenance and emergency repair.','<h2>Reusable Hydraulic Fitting</h2><p>This fitting can be assembled without a crimping machine and is available in carbon steel, stainless steel and brass.</p><h3>Features</h3><ul><li>Fast field installation</li><li>Multiple thread standards</li><li>Corrosion-resistant finishes</li></ul>','https://www.hbfittings.net/uploads/33800/small/hydraulic-hose-reusable-fitting1e824.png','','Carbon steel / stainless steel / brass','1/4-1 in','BSP / NPT','Up to 5000 PSI','-40 C to 120 C','100 pcs','ISO / SAE','Hydraulic hose repair','reusable fitting,hydraulic hose fitting,BSP fitting',1,1,60,1,NOW(3),NOW(3)),
(7,701,'Male Pipe Reusable Hydraulic Hose Fitting','male-pipe-reusable-hydraulic-hose-fitting','DP-HY-MP','Straight male pipe reusable fitting for single-wire hydraulic hose assemblies.','<h2>Product Overview</h2><p>Machined threads and a robust socket provide a secure reusable connection for field service.</p><h3>Inspection</h3><p>Thread gauges and dimensional controls are applied throughout production.</p>','https://www.hbfittings.net/uploads/202633800/small/male-pipe-reusable-hydraulic-hose-fittingc946c90e-98c8-4db7-9ad6-c3bfe40d195f.webp','','Carbon steel','1/4-1 in','NPT / BSPT male','Up to 5000 PSI','-40 C to 120 C','100 pcs','SAE / ISO','Mobile and industrial hydraulics','male pipe fitting,reusable hose fitting,hydraulic adapter',1,1,70,1,NOW(3),NOW(3)),
(8,702,'JIC 37 Swivel Reusable Hydraulic Hose Fitting','jic-37-swivel-reusable-hydraulic-hose-fitting','DP-HY-JIC37','JIC 37-degree female swivel reusable fitting for convenient hose routing and maintenance.','<h2>Product Details</h2><p>The swivel nut supports convenient installation while the 37-degree cone provides a reliable metal-to-metal seal.</p><h3>Material Options</h3><p>Carbon steel and stainless steel versions are available.</p>','https://www.hbfittings.net/uploads/202633800/small/jic-37-swivel-reusable-hydraulic-hose-fitting1eabf2ce-ba27-4461-a832-ae51e521651e.webp','','Carbon steel / stainless steel','1/4-1 in','JIC 37 female swivel','Up to 5000 PSI','-40 C to 120 C','100 pcs','SAE J514','Hydraulic hose assembly','JIC 37 fitting,swivel fitting,reusable hose fitting',1,1,80,1,NOW(3),NOW(3)),
(9,8,'High Pressure Forged Stainless Steel Elbow','high-pressure-forged-stainless-steel-elbow','DP-FG-EL90','Forged 90-degree elbow for high-pressure threaded and socket-weld piping.','<h2>Forged Pipe Fitting</h2><p>Manufactured from forged stainless steel for compact, high-strength pressure connections.</p><h3>Standards</h3><p>Dimensional and material configurations are available to ASME B16.11 and customer drawings.</p>','https://www.hbfittings.net/uploads/33800/small/high-quality-high-pressure-elbow-forged-pipe61906.png','','Stainless steel 304 / 316','1/8-4 in','NPT / BSP / socket weld','Class 3000 / 6000 / 9000','-196 C to 400 C','50 pcs','ASME B16.11','Oil, gas, chemical and power','forged elbow,high pressure fitting,stainless steel elbow',1,1,90,1,NOW(3),NOW(3)),
(10,8,'Forged 316 Stainless Steel Pipe Fitting','forged-316-stainless-steel-pipe-fitting','DP-FG-316','Corrosion-resistant forged 316 stainless steel fitting for chemical and offshore service.','<h2>Production Introduction</h2><p>Forged construction and controlled machining provide strength, dimensional consistency and corrosion resistance.</p><h3>Testing</h3><p>Material verification and dimensional inspection are available for critical projects.</p>','https://www.hbfittings.net/uploads/33800/small/forged-316-stainless-steel-pipe-fittings532bc.png','','316 / 316L stainless steel','1/8-4 in','NPT / socket weld','Class 3000 / 6000','-196 C to 400 C','50 pcs','ASME B16.11','Chemical, marine and offshore','316 fitting,forged pipe fitting,chemical fitting',1,1,100,1,NOW(3),NOW(3)),
(11,8,'High Pressure Stainless Steel Pipe Nipple','high-pressure-stainless-steel-pipe-nipple','DP-SS-NP','Precision-machined stainless steel pipe nipple for high-pressure threaded systems.','<h2>Stainless Steel Pipe Nipple</h2><p>Available in close, hex and extended configurations with NPT, BSPT or customer-specific threads.</p><h3>OEM Service</h3><p>Length, material, thread and surface finish can be produced to drawing.</p>','https://www.hbfittings.net/uploads/33800/small/high-pressure-stainless-steel-pipe-nipple645f7.png','','304 / 316 stainless steel','1/8-4 in','NPT / BSPT','Up to 6000 PSI','-196 C to 400 C','100 pcs','ASME / OEM','Process piping and instrumentation','pipe nipple,stainless steel nipple,high pressure fitting',1,1,110,1,NOW(3),NOW(3)),
(12,601,'Stainless Steel Compression Union Tee','stainless-steel-compression-union-tee','DP-CT-UT','Double-ferrule union tee for leak-tight tube branching in instrumentation systems.','<h2>Production Introduction</h2><p>The Depo compression union tee connects three equal-size tubes using a two-ferrule design that supports repeatable, leak-tight assembly.</p><p><img src="https://www.hbfittings.net/uploads/33800/small/stainless-steel-threaded-eccentric-couplingc403d.png" alt="compression fitting"></p><h3>Products Feature</h3><ul><li>316 stainless steel construction</li><li>Precision-machined ferrules and body</li><li>Compatible with common fractional and metric tubing</li></ul><h3>Why Choose Us</h3><p>Full CNC production, material traceability and 100% outgoing inspection support demanding industrial projects.</p>','https://www.hbfittings.net/uploads/33800/small/stainless-steel-threaded-eccentric-couplingc403d.png','', '316 stainless steel','1/8-1 in, 3-25 mm','Double ferrule tube connection','Up to 6000 PSI','-196 C to 400 C','50 pcs','ASTM / OEM','Instrumentation, hydrogen and laboratory','compression union tee,double ferrule fitting,316 tube fitting',1,1,120,1,NOW(3),NOW(3));
