INSERT INTO `content_pages` (`id`,`title`,`slug`,`subtitle`,`content`,`cover_image`,`template`,`sort`,`status`,`created_at`,`updated_at`) VALUES
(1,'About Us','about-us','Professional brass and stainless steel valve and fitting manufacturer since 2007.','<p>Hubei Depo Valve and Fitting Co., Ltd. is a professional manufacturer of brass and stainless steel valves and fittings in China. Our headquarters, Wenzhou Hi-Tek Valve & Fitting Co., Ltd., was founded in 2007.</p><h2>Integrated Manufacturing Capability</h2><p>We operate brass and stainless steel production resources in mainland China and Taiwan. Full CNC machining, automated production lines and advanced testing equipment support product development, manufacturing, sales and after-sales service.</p><h2>Materials and Markets</h2><p>Available materials include CA360, CA345, CA377, DZR brass, lead-free brass C46500, stainless steel 304 and 316, duplex steel, Monel and aluminum. Our products serve oil and gas, pharmaceutical, food and beverage, chemical, water treatment, HVAC, automotive and industrial automation markets.</p><h2>Quality Control & Test Equipment</h2><p>Quality is the lifeblood of every Depo product. Our production team follows controlled inspection procedures from incoming material to final shipment, with training, calibrated gauges, pressure testing and complete outgoing inspection.</p><h2>Mission & Vision</h2><p>Our mission is to make global fluid connections safer, simpler and more dependable. Our vision is to build lasting customer partnerships through engineering support, honest communication and consistent quality.</p>','https://www.hbfittings.net/uploads/33800/index/3.jpg','about',10,1,NOW(3),NOW(3)),
(2,'Company Profile','company-profile','A family-owned manufacturer serving global industrial customers.','<p>Depo brings together product development, machining, assembly, inspection, export service and after-sales support. Our team works with distributors, equipment manufacturers and project contractors throughout North America, Europe and other developed markets.</p><h2>Our Capabilities</h2><ul><li>Full CNC and multi-axis machining</li><li>Automated production and controlled assembly</li><li>Pressure, sealing and dimensional inspection</li><li>Material, thread, logo and packaging customization</li><li>Consolidated shipment and global logistics support</li></ul>','https://www.hbfittings.net/uploads/33800/index/2.jpg','standard',20,1,NOW(3),NOW(3)),
(3,'OEM','oem','From a drawing or sample to dependable volume production.','<p>Our OEM and ODM process covers requirement review, material recommendation, design-for-manufacturing feedback, sampling, validation and controlled production.</p><h2>What We Can Customize</h2><p>Material, size, thread, pressure rating, surface treatment, laser logo, handle color, individual packaging and carton artwork can be tailored to your market.</p><h2>Start Your Project</h2><p>Send a drawing, sample photo, BOM or target standard. Our engineers will review feasibility and provide a practical production proposal.</p>','https://www.hbfittings.net/uploads/33800/index/4.jpg','standard',30,1,NOW(3),NOW(3)),
(4,'Materials','materials','Material choices matched to pressure, media, temperature and compliance needs.','<h2>Brass</h2><p>CA360, CA345, CA377, DZR grades CW602N and CW617N, and lead-free C46500 are available for plumbing, gas and industrial applications.</p><h2>Stainless Steel and Special Alloys</h2><p>304, 316 and 316L stainless steel are standard options. Duplex steel, super duplex, Monel, carbon steel and aluminum can be evaluated for special projects.</p><h2>Material Control</h2><p>Certificates, traceability and third-party testing can be arranged according to the order and applicable specification.</p>','https://www.hbfittings.net/uploads/33800/index/5.jpg','standard',40,1,NOW(3),NOW(3)),
(5,'Service','service','Responsive support before, during and after production.','<h2>Engineering Support</h2><p>Our team assists with product selection, thread and material compatibility, custom design review and sample development.</p><h2>Order Execution</h2><p>Clear milestones, production updates, outgoing inspection and flexible shipping options keep international orders predictable.</p><h2>After-Sales</h2><p>We respond quickly to technical questions and provide corrective support whenever a delivered product requires investigation.</p>','https://www.hbfittings.net/uploads/33800/index/6.jpg','standard',50,1,NOW(3),NOW(3)),
(6,'FAQ','faq','Common questions from international buyers.','<h2>What is your minimum order quantity?</h2><p>MOQ depends on the product and customization. Standard items may start from 50 to 500 pieces.</p><h2>Can you manufacture from a drawing or sample?</h2><p>Yes. OEM and ODM development is a core service. Please send dimensions, material, quantity and operating requirements.</p><h2>Which certifications are available?</h2><p>Depo maintains ISO quality management and offers selected NSF, UPC, lead-free and market-specific certified products.</p><h2>How quickly do you reply?</h2><p>Our sales and engineering team normally responds within 24 hours.</p>','https://www.hbfittings.net/uploads/33800/index/7.jpg','standard',60,1,NOW(3),NOW(3)),
(7,'Privacy Policy','privacy-policy','How we handle website and inquiry information.','<p>We collect only the contact and project information needed to answer inquiries, prepare quotations, provide technical recommendations and improve customer service.</p><p>We do not sell personal information. Submitted drawings and project details are treated as confidential business information and are shared only with team members who need them to support the request.</p><p>Contact summer@hbfittings.net to request access, correction or deletion of submitted personal information.</p>','https://www.hbfittings.net/uploads/33800/index/8.jpg','policy',70,1,NOW(3),NOW(3));
