INSERT INTO `industries` (`title`,`subtitle`,`description`,`image_url`,`link_url`,`sort`,`status`,`created_at`,`updated_at`) VALUES
('Pharmaceutical & Food','Protecting purity from process to product','Depo provides corrosion-resistant, cleanable fluid components for pharmaceutical, biotechnology, food and beverage systems. Reliable sealing and carefully controlled materials help minimize contamination risk and support stable production.','https://www.hbfittings.net/uploads/33800/index/1.jpg','/products',10,1,NOW(3),NOW(3)),
('Hydrogen Energy','Develop hydrogen energy for a greener future','Hydrogen storage, transport and refueling equipment requires strict pressure resistance and sealing. Depo supplies high-performance fittings and valves tailored to demanding hydrogen service.','https://www.hbfittings.net/uploads/33800/index/2.jpg','/products',20,1,NOW(3),NOW(3)),
('Petroleum & Petrochemical','Advancing energy exploration and production','Our tube fittings, instrument valves and related components serve measurement, calibration, sampling and process control systems throughout petroleum and petrochemical facilities.','https://www.hbfittings.net/uploads/33800/index/3.jpg','/products',30,1,NOW(3),NOW(3)),
('Refinery & Chemical','Safe, leak-free fluid systems','Professional fluid solutions support fixed plants, offshore platforms, natural gas processing, transmission, storage and other demanding refinery and chemical operations.','https://www.hbfittings.net/uploads/33800/index/4.jpg','/products',40,1,NOW(3),NOW(3)),
('CNG & LNG','Safety-centered solutions for natural gas systems','High-pressure, corrosion-resistant tube fittings and control valves are designed to maintain sealing performance and long-term stability in CNG and LNG service.','https://www.hbfittings.net/uploads/33800/index/5.jpg','/products',50,1,NOW(3),NOW(3)),
('Laboratory','Accuracy begins with stable fluid control','Precision fittings and valves support spectrometers, chromatographs, liquid analyzers and other laboratory instruments that depend on consistent flow and leak-tight connections.','https://www.hbfittings.net/uploads/33800/index/6.jpg','/products',60,1,NOW(3),NOW(3)),
('Solar Energy & Semiconductor','Driving progress with renewable energy','High-purity components and custom fluid solutions support reliable production and auxiliary systems in photovoltaic and semiconductor manufacturing.','https://www.hbfittings.net/uploads/33800/index/7.jpg','/products',70,1,NOW(3),NOW(3)),
('HVAC System','Comfortable and reliable climate control','Brass fittings, test plugs, syphon tubes, needle valves and control components provide dependable sealing and straightforward installation for HVAC and refrigeration systems.','https://www.hbfittings.net/uploads/33800/index/8.jpg','/products',80,1,NOW(3),NOW(3)),
('Thermal & Nuclear Power','Components for critical power systems','A diverse fitting and valve range supports steam-water, power generation, instrument and control systems where safety, documentation and operating reliability are essential.','https://www.hbfittings.net/uploads/33800/index/9.jpg','/products',90,1,NOW(3),NOW(3));
INSERT INTO `content_articles` (`content_type`,`category`,`title`,`slug`,`summary`,`content`,`cover_image`,`published_at`,`featured`,`sort`,`status`,`created_at`,`updated_at`) VALUES
('news','Customer feedback','Custom Aluminum Garden Hose Fittings Delivered to the USA','custom-aluminum-garden-hose-fittings-usa','A custom material recommendation helped a U.S. customer control cost while achieving the requested silver finish.','<h2>From Rising Brass Prices to a Better Solution</h2><p>A U.S. customer required 2,000 custom garden hose fittings but needed an alternative to rising brass costs and preferred a silver appearance. Our engineering team evaluated the application and recommended a customized aluminum fitting.</p><h2>Fast Engineering and Flexible Production</h2><p>We reviewed the requirements, optimized the design, prepared samples and arranged production around the customer timeline. Free laser marking and tailored packaging were included.</p><h2>A Long-Term Result</h2><p>The customer confirmed satisfaction with product quality, communication and delivery, and plans to continue cooperation on larger projects.</p>','https://www.hbfittings.net/uploads/33800/news/n202607291544016baf6.jpg','2026-07-29 15:44:00',1,10,1,NOW(3),NOW(3)),
('news','Customer orders case','2,000 Compression Fittings Delivered to Kazakhstan in 10 Days','compression-fittings-delivered-kazakhstan','A coordinated production and land-transport plan moved 2,000 stainless steel compression fittings to Kazakhstan in ten days.','<h2>Project Requirement</h2><p>The customer required a fast delivery of stainless steel compression fittings with clear dimensional inspection and export packing.</p><h2>Execution</h2><p>Available material and production capacity were coordinated immediately. Inspection, labeling and consolidated land transport kept the project on schedule.</p><h2>Outcome</h2><p>The fittings arrived within the requested ten-day window and the customer approved the order for future repeat business.</p>','https://www.hbfittings.net/uploads/202133800/n202108121437007083268.jpg','2026-07-15 09:30:00',1,20,1,NOW(3),NOW(3)),
('news','shipment news','Lead-Free Brass Mini Ball Valve Shipment to USA','lead-free-brass-mini-ball-valve-shipment-usa','Lead-free C46500 mini ball valves completed inspection and export packing for a U.S. plumbing customer.','<h2>Product and Material</h2><p>The order used lead-free C46500 brass with custom dimensions and packaging for the U.S. plumbing market.</p><h2>Inspection</h2><p>Thread gauges, dimensional checks and leak tests were completed before individual protection and carton packing.</p>','https://www.hbfittings.net/uploads/33800/news/n20260509222859fe628.jpg','2026-05-09 22:28:00',1,30,1,NOW(3),NOW(3)),
('news','Company culture','Meet Our Overseas Sales Manager Summer','meet-sales-manager-summer','Professional service is built by people who understand both product details and international customer expectations.','<h2>Customer-Focused Communication</h2><p>Summer coordinates quotations, technical reviews, production milestones and shipping details for international projects.</p><p>Her approach combines fast response with careful requirement confirmation so customers receive practical solutions instead of generic answers.</p>','https://www.hbfittings.net/uploads/202633800/nad9e6aae-6639-4aef-827b-8ddff9bd5c8c.jpg','2026-04-14 10:00:00',1,40,1,NOW(3),NOW(3)),
('knowledge','brass valve','How Does a Brass Male-to-Female Needle Valve Work?','how-brass-male-female-needle-valve-works','A practical explanation of the stem, needle and seat used to regulate flow accurately.','<h2>Operating Principle</h2><p>Turning the handle moves a finely tapered needle toward or away from the valve seat. The small, controlled change in opening provides much more precise throttling than a ball valve.</p><h2>Selection Points</h2><p>Confirm thread type, material compatibility, pressure, temperature and whether the application requires panel mounting or a lockable handle.</p>','https://www.hbfittings.net/Content/uploads/2021806904/20210618094714fc7ea8c7bc62444280951f16881dd15d.jpg','2026-03-28 08:30:00',0,10,1,NOW(3),NOW(3)),
('knowledge','material','Choosing Brass, DZR Brass or Stainless Steel','choosing-brass-dzr-stainless-steel','Compare common fitting materials based on media, corrosion, temperature, regulations and lifecycle cost.','<h2>Standard Brass</h2><p>Machinable brass is cost-effective for many air, water and general industrial connections.</p><h2>DZR and Lead-Free Brass</h2><p>DZR grades improve resistance in aggressive water conditions, while lead-free grades support regulated potable-water markets.</p><h2>Stainless Steel</h2><p>304 and 316 stainless steel provide higher temperature capability, strength and corrosion resistance for chemical, marine and instrumentation service.</p>','https://www.hbfittings.net/uploads/33800/index/7.jpg','2026-03-12 08:30:00',0,20,1,NOW(3),NOW(3)),
('knowledge','hydraulic fittings','Understanding BSP and JIC Hydraulic Connections','understanding-bsp-jic-hydraulic-connections','How BSPP, BSPT and JIC 37-degree connections seal and where each standard is commonly used.','<h2>BSPP and BSPT</h2><p>BSPP threads are parallel and typically seal with a bonded washer or cone. BSPT threads are tapered and seal on the thread with an appropriate sealant.</p><h2>JIC 37 Degree</h2><p>JIC fittings use a 37-degree metal flare and are widely used in mobile and industrial hydraulic systems.</p>','https://www.hbfittings.net/uploads/202633800/small/jic-37-swivel-reusable-hydraulic-hose-fitting1eabf2ce-ba27-4461-a832-ae51e521651e.webp','2026-02-21 08:30:00',0,30,1,NOW(3),NOW(3)),
('blog','Product Guide','What Pressure Rating Should a Brass Fitting Have?','pressure-rating-brass-fitting','Pressure rating depends on alloy, geometry, size, temperature, connection type and the governing standard.','<h2>There Is No Single Universal Rating</h2><p>Two fittings made from the same brass may have different ratings because wall thickness, shape and thread design change stress distribution.</p><h2>Ask the Right Questions</h2><p>Confirm maximum working and surge pressure, temperature, media, cycle frequency, applicable standard and safety factor before selection.</p>','https://www.hbfittings.net/Content/uploads/2021806904/2021061809482191882e6e776d427097002d6e5c760602.jpg','2026-01-30 08:30:00',0,10,1,NOW(3),NOW(3)),
('blog','Engineering','Seven Details to Include in an OEM Fitting Drawing','details-oem-fitting-drawing','A complete drawing reduces sampling time and prevents assumptions about threads, tolerances and sealing surfaces.','<h2>Essential Drawing Details</h2><ol><li>Material and material standard</li><li>Complete dimensions and tolerances</li><li>Thread designation and gauge standard</li><li>Sealing surfaces</li><li>Pressure and temperature</li><li>Surface finish or plating</li><li>Marking and packaging</li></ol><p>A physical sample and application information are also valuable when a legacy drawing is incomplete.</p>','https://www.hbfittings.net/uploads/33800/index/2.jpg','2026-01-16 08:30:00',0,20,1,NOW(3),NOW(3)),
('blog','Maintenance','How to Avoid Leaks in Compression Tube Fittings','avoid-leaks-compression-tube-fittings','Correct tube preparation, insertion and make-up are essential for repeatable double-ferrule fitting performance.','<h2>Prepare the Tube</h2><p>Cut the tube square, remove burrs and confirm the outside surface is free from deep scratches.</p><h2>Assemble Correctly</h2><p>Insert the tube fully against the shoulder, follow the specified nut rotation and avoid mixing components from incompatible systems.</p><h2>Inspect the System</h2><p>Support tubing against vibration and complete a controlled leak test before operation.</p>','https://www.hbfittings.net/uploads/33800/small/stainless-steel-threaded-eccentric-couplingc403d.png','2025-12-18 08:30:00',0,30,1,NOW(3),NOW(3)),
('blog','Materials','Why 316 Stainless Steel Is Used in Process Instrumentation','why-316-stainless-steel-process-instrumentation','Molybdenum-bearing 316 stainless steel offers valuable corrosion resistance across many process environments.','<h2>Corrosion Performance</h2><p>316 stainless steel generally performs better than 304 in chloride-containing and many chemical environments, though exact suitability still depends on concentration and temperature.</p><h2>System Compatibility</h2><p>Material selection must consider tubing, valves, fittings, media, cleaning chemicals and external atmosphere as a complete system.</p>','https://www.hbfittings.net/uploads/33800/small/forged-316-stainless-steel-pipe-fittings532bc.png','2025-11-25 08:30:00',0,40,1,NOW(3),NOW(3));
INSERT INTO `videos` (`title`,`description`,`cover_url`,`video_url`,`sort`,`status`,`created_at`,`updated_at`) VALUES
('Inside the Depo Factory','A look at CNC machining, production organization and quality inspection.','https://www.hbfittings.net/uploads/33800/index/2.jpg','https://www.youtube.com/watch?v=WfXRP5cPMo8',10,1,NOW(3),NOW(3)),
('Pressure and Leakage Testing','See how valves and fittings are checked before shipment.','https://www.hbfittings.net/uploads/33800/index/3.jpg','https://www.youtube.com/watch?v=WfXRP5cPMo8',20,1,NOW(3),NOW(3)),
('OEM Product Development','From customer drawing and sample review to controlled production.','https://www.hbfittings.net/uploads/33800/index/4.jpg','https://www.youtube.com/watch?v=WfXRP5cPMo8',30,1,NOW(3),NOW(3)),
('Export Packing and Shipment','Protective packaging, labels and consolidated international shipping.','https://www.hbfittings.net/uploads/33800/index/8.jpg','https://www.youtube.com/watch?v=WfXRP5cPMo8',40,1,NOW(3),NOW(3));
